  "text.b4126b3d0d1c0a8806a5": "cash_capex",
  "text.c050f7b020ddbd36ce2c": "approximate_lower_bound",
  "text.d28659b6263ffbcf6695": "實際值來源",
  "text.08200455c601cd00e599": "實際值來源 · 6 個欄位",
  "text.1e2c4c8c50ef29916d41": "at_or_above_approximate_floor",
  "text.2e378951281ec59f568e": "相對下限的誤差",
  "text.596d40a4ed24c02a31b1": "條件",
  "text.4776690e897eb869422c": "現金支付時點可能變動；不是狹窄區間。",
