  "text.aef1a4cb9ad1b7e9de24": "semi-megapack-volume",
  "text.aa3e3757abb2d28a3762": "Semi／Megapack 3 量產",
  "text.691070afd32a84332805": "最新展望稱 2026 年開始生產",
  "text.4008098e48cbf5232462": "待定；措辭由量產弱化為開始生產",
  "text.e188303b8d9c9fa0105c": "optimus-public-sales",
